-- customer_interaction.sql: deterministic generator for SILVER.CUSTOMER_INTERACTION (~32k rows), appended to
-- sql/01_silver_data.sql. All randomness is HASH-seeded, so every install produces
-- identical rows (checked by HASH_AGG against the reference). Seeds use the CUS- form of the party id, which is
-- how the data was first generated; the stored key is PARTY_ID.
-- Story: mobile adoption grows month by month, online banking is used by a subset, branch declines, and
-- September 2026 has a contact-centre complaint spike.
CREATE OR REPLACE TABLE CUSTOMER_INTERACTION (
    INTERACTION_ID   VARCHAR,
    PARTY_ID         VARCHAR,
    CHANNEL          VARCHAR(14),
    INTERACTION_DATE DATE,
    INTERACTION_TYPE VARCHAR(19),
    SOURCE_SYSTEM    VARCHAR(12)
) COMMENT = 'Customer interactions by channel: Mobile app, Online banking, Branch, Contact centre. Types: Login, Payment, Enquiry, Product application, Complaint. Source: channel platforms (synthetic).';

INSERT INTO CUSTOMER_INTERACTION
WITH months AS (
  SELECT MONTH_END_DATE, DATE_TRUNC(month, MONTH_END_DATE) month_start, ROW_NUMBER() OVER (ORDER BY MONTH_END_DATE) - 1 idx
  FROM MONTH_END_CALENDAR),
channels AS (
  SELECT * FROM VALUES
   ('Mobile app','RETAIL',4.5, 0.02),('Online banking','RETAIL',1.8,-0.010),('Branch','RETAIL',0.30,-0.030),('Contact centre','RETAIL',0.28,0.0),
   ('Mobile app','PREMIER',3.5,0.02),('Online banking','PREMIER',2.2,-0.005),('Branch','PREMIER',0.70,-0.020),('Contact centre','PREMIER',0.45,0.0),
   ('Mobile app','SME',2.0,0.03),('Online banking','SME',4.5,0.000),('Branch','SME',0.45,-0.020),('Contact centre','SME',0.75,0.0)
   AS c(channel, segment, rate, trend)),
cust AS (
  SELECT REPLACE(PARTY_ID, 'PTY-', 'CUS-') AS CUSTOMER_ID, CUSTOMER_SEGMENT, ONBOARDED_DATE,
         MOD(ABS(HASH(REPLACE(PARTY_ID, 'PTY-', 'CUS-'),'mob')),100) hm, MOD(ABS(HASH(REPLACE(PARTY_ID, 'PTY-', 'CUS-'),'onl')),100) ho
  FROM PARTY
  WHERE MOD(ABS(HASH(REPLACE(PARTY_ID, 'PTY-', 'CUS-'),'dormant')),100) >= 12),
cells AS (
  SELECT c.CUSTOMER_ID, m.month_start, m.MONTH_END_DATE, m.idx, ch.channel,
         FLOOR(GREATEST(ch.rate * (1 + ch.trend * m.idx) * IFF(ch.channel='Contact centre' AND m.MONTH_END_DATE='2026-09-30', 1.8, 1), 0)
               + UNIFORM(0::FLOAT, 1::FLOAT, HASH(c.CUSTOMER_ID, m.idx, ch.channel))) AS n
  FROM cust c
  JOIN channels ch ON ch.segment = c.CUSTOMER_SEGMENT
  JOIN months m ON m.MONTH_END_DATE >= c.ONBOARDED_DATE
  WHERE CASE ch.channel
          WHEN 'Mobile app' THEN c.hm < 30 OR (c.hm < 85 AND m.idx >= FLOOR((c.hm - 30) / 3.5))
          WHEN 'Online banking' THEN c.ho < CASE c.CUSTOMER_SEGMENT WHEN 'RETAIL' THEN 50 WHEN 'PREMIER' THEN 70 ELSE 90 END
          ELSE TRUE END),
seq AS (SELECT SEQ4() k FROM TABLE(GENERATOR(ROWCOUNT => 20))),
ev AS (
  SELECT cells.*, seq.k, MOD(ABS(HASH(cells.CUSTOMER_ID, cells.idx, cells.channel, seq.k, 'type')),100) AS h
  FROM cells JOIN seq ON seq.k < cells.n)
SELECT
  'INT-' || LPAD(ROW_NUMBER() OVER (ORDER BY month_start, CUSTOMER_ID, channel, k)::STRING, 7, '0'),
  REPLACE(CUSTOMER_ID, 'CUS-', 'PTY-'),
  channel,
  DATEADD(day, MOD(ABS(HASH(CUSTOMER_ID, idx, channel, k)), DAY(MONTH_END_DATE)), month_start),
  CASE channel
    WHEN 'Mobile app' THEN CASE WHEN h < 55 THEN 'Login' WHEN h < 92 THEN 'Payment' WHEN h < 98 THEN 'Enquiry' ELSE 'Product application' END
    WHEN 'Online banking' THEN CASE WHEN h < 45 THEN 'Login' WHEN h < 85 THEN 'Payment' WHEN h < 95 THEN 'Enquiry' ELSE 'Product application' END
    WHEN 'Branch' THEN CASE WHEN h < 50 THEN 'Enquiry' WHEN h < 80 THEN 'Payment' WHEN h < 95 THEN 'Product application' ELSE 'Complaint' END
    ELSE CASE WHEN h < IFF(MONTH_END_DATE='2026-09-30', 55, 75) THEN 'Enquiry' WHEN h < 82 THEN 'Product application' ELSE 'Complaint' END
  END,
  'CHANNELS'
FROM ev;

UPDATE CUSTOMER_INTERACTION
SET INTERACTION_TYPE = CASE WHEN MOD(ABS(HASH(INTERACTION_ID,'sep')),100) < 42 THEN 'Enquiry'
                            WHEN MOD(ABS(HASH(INTERACTION_ID,'sep')),100) < 58 THEN 'Product application' ELSE 'Complaint' END
WHERE CHANNEL = 'Contact centre' AND INTERACTION_DATE >= '2026-09-01';

-- =====================================================================================================================
-- sql/02_semantic_view.sql
-- =====================================================================================================================
-- 02_semantic_view.sql: governed semantic view over the Silver layer, with verified queries.
-- Built from YAML so the verified queries are kept (GET_DDL drops them).
USE WAREHOUSE BANK_DEMO_WH;

-- Inputs to the semantic view. Each one pre-joins the columns its metrics need, so every expression in the
-- semantic view stays within its own logical table: an agent's Cortex Analyst tool leaves out facts, dimensions
-- and metrics whose expression references another logical table (observed November 2026). The row access
-- policies on the Silver tables still apply through these views.
CREATE OR REPLACE VIEW BANK_DEMO.SEMANTIC.ACCOUNT_BALANCE_INPUT
  COMMENT = 'Input to RETAIL_BANKING_SV: month-end balances with the account holder and their KYC status' AS
SELECT b.ARRANGEMENT_ID, b.SNAPSHOT_DATE, b.LEDGER_BALANCE_GBP,
       a.PARTY_ID AS HOLDER_PARTY_ID, p.KYC_STATUS AS HOLDER_KYC_STATUS
FROM BANK_DEMO.SILVER.CURRENT_ACCOUNT_BALANCE_SNAPSHOT b
LEFT JOIN BANK_DEMO.SILVER.CURRENT_ACCOUNT_ARRANGEMENT a ON a.ARRANGEMENT_ID = b.ARRANGEMENT_ID
LEFT JOIN BANK_DEMO.SILVER.PARTY p ON p.PARTY_ID = a.PARTY_ID;

CREATE OR REPLACE VIEW BANK_DEMO.SEMANTIC.LOAN_POSITION_INPUT
  COMMENT = 'Input to RETAIL_BANKING_SV: month-end loan positions with the borrower and the maturity date' AS
SELECT s.LOAN_ID, s.SNAPSHOT_DATE, s.OUTSTANDING_PRINCIPAL_GBP, s.DAYS_PAST_DUE,
       l.PARTY_ID AS BORROWER_PARTY_ID, l.MATURITY_DATE
FROM BANK_DEMO.SILVER.LOAN_POSITION_SNAPSHOT s
LEFT JOIN BANK_DEMO.SILVER.LOAN_ARRANGEMENT l ON l.LOAN_ID = s.LOAN_ID;

CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_YAML('BANK_DEMO.SEMANTIC', $$
name: RETAIL_BANKING_SV
description: 'Retail banking semantic view over the SILVER layer (synthetic demo bank): customers and their relationship managers, month-end current account balances, loans with maturity, arrears and the NPL and loan-to-deposit ratios, and customer interactions by channel. Monthly data from June 2025 to September 2026.'
tables:
- name: ACCOUNT_BALANCE
  description: Month-end ledger balance per current account, with the account holder and their KYC status
  base_table:
    database: BANK_DEMO
    schema: SEMANTIC
    table: ACCOUNT_BALANCE_INPUT
  primary_key:
    columns:
    - ARRANGEMENT_ID
    - SNAPSHOT_DATE
  facts:
  - name: VERIFIED_HOLDER_PARTY_ID
    description: Party holding the account, only when KYC is verified
    expr: IFF(HOLDER_KYC_STATUS = 'VERIFIED', HOLDER_PARTY_ID, NULL)
    data_type: VARCHAR(134217728)
    access_modifier: public_access
  metrics:
  - name: ACTIVE_CUSTOMERS
    synonyms:
    - active customers
    - active parties
    description: Parties with KYC VERIFIED holding at least one open current account at month end
    expr: COUNT(DISTINCT account_balance.verified_holder_party_id)
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
  - name: TOTAL_DEPOSITS
    synonyms:
    - deposits
    - customer deposits
    - deposit balances
    - balance
    - balances
    - customer balance
    - deposit balance
    description: Sum of month-end current account ledger balances, GBP. Semi-additive over time
    expr: SUM(LEDGER_BALANCE_GBP)
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
- name: CALENDAR
  description: Shared month-end reporting calendar
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: MONTH_END_CALENDAR
  primary_key:
    columns:
    - MONTH_END_DATE
  dimensions:
  - name: MONTH_END_DATE
    synonyms:
    - reporting date
    - snapshot date
    - as at date
    - month end
    description: Month-end reporting date for balances and positions
    expr: MONTH_END_DATE
    data_type: DATE
    access_modifier: public_access
- name: CURRENT_ACCOUNT
  synonyms:
  - current account
  - deposit account
  - CASA
  description: Current Account Arrangement (core banking platform)
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: CURRENT_ACCOUNT_ARRANGEMENT
  primary_key:
    columns:
    - ARRANGEMENT_ID
  dimensions:
  - name: HOLDER_PARTY_ID
    expr: PARTY_ID
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: OPENED_DATE
    expr: OPENED_DATE
    data_type: DATE
    access_modifier: public_access
  - name: PRODUCT_NAME
    description: Current account product
    expr: PRODUCT_NAME
    data_type: VARCHAR(24)
    access_modifier: public_access
- name: INTERACTION
  synonyms:
  - visits
  - activity
  - customer contacts
  - sessions
  description: 'Every customer interaction by channel: mobile app, online banking, branch visit or contact centre call'
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: CUSTOMER_INTERACTION
  primary_key:
    columns:
    - INTERACTION_ID
  dimensions:
  - name: CHANNEL
    synonyms:
    - channel
    - touchpoint
    description: Mobile app, Online banking, Branch or Contact centre
    expr: CHANNEL
    data_type: VARCHAR(14)
    access_modifier: public_access
  - name: CHANNEL_GROUP
    synonyms:
    - digital vs assisted
    description: Digital (app, online) or Assisted (branch, contact centre)
    expr: IFF(CHANNEL IN ('Mobile app', 'Online banking'), 'Digital', 'Assisted')
    data_type: VARCHAR(8)
    access_modifier: public_access
  - name: INTERACTION_DATE
    synonyms:
    - visit date
    - activity date
    expr: INTERACTION_DATE
    data_type: DATE
    access_modifier: public_access
  - name: INTERACTION_MONTH
    synonyms:
    - activity month
    - visit month
    description: First day of the month of the interaction
    expr: DATE_TRUNC('MONTH', INTERACTION_DATE)
    data_type: DATE
    access_modifier: public_access
  - name: INTERACTION_TYPE
    synonyms:
    - activity type
    - reason
    description: Login, Payment, Enquiry, Product application or Complaint
    expr: INTERACTION_TYPE
    data_type: VARCHAR(19)
    access_modifier: public_access
  facts:
  - name: IS_COMPLAINT
    expr: IFF(INTERACTION_TYPE = 'Complaint', 1, 0)
    data_type: NUMBER(1,0)
    access_modifier: public_access
  - name: IS_DIGITAL
    expr: IFF(CHANNEL IN ('Mobile app', 'Online banking'), 1, 0)
    data_type: NUMBER(1,0)
    access_modifier: public_access
  metrics:
  - name: ACTIVE_CHANNEL_USERS
    synonyms:
    - active users
    - unique customers
    - customers using the channel
    description: Distinct customers with at least one interaction
    expr: COUNT(DISTINCT PARTY_ID)
    access_modifier: public_access
  - name: COMPLAINTS
    synonyms:
    - complaint count
    description: Interactions recorded as a complaint
    expr: SUM(interaction.is_complaint)
    access_modifier: public_access
  - name: DIGITAL_SHARE
    synonyms:
    - digital adoption
    - digital share
    description: Share of interactions through mobile app or online banking
    expr: DIV0(SUM(interaction.is_digital), COUNT(INTERACTION_ID))
    access_modifier: public_access
  - name: INTERACTIONS
    synonyms:
    - visits
    - activity
    - contacts
    - interaction count
    description: Number of customer interactions
    expr: COUNT(INTERACTION_ID)
    access_modifier: public_access
- name: LOAN
  synonyms:
  - loan
  - lending facility
  - credit facility
  description: 'Loan Arrangement: personal loans and SME term loans with term and maturity date (core banking platform)'
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: LOAN_ARRANGEMENT
  primary_key:
    columns:
    - LOAN_ID
  dimensions:
  - name: BORROWER_PARTY_ID
    description: Customer who holds the loan
    expr: PARTY_ID
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: INTEREST_RATE_PCT
    synonyms:
    - rate
    - interest rate
    description: Contractual annual interest rate, %
    expr: INTEREST_RATE_PCT
    data_type: NUMBER(5,2)
    access_modifier: public_access
  - name: LOAN_CATEGORY
    description: CONSUMER_LOAN or CORPORATE_LOAN
    expr: LOAN_CATEGORY
    data_type: VARCHAR(14)
    access_modifier: public_access
  - name: LOAN_ID
    expr: LOAN_ID
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: LOAN_PRODUCT
    description: Personal Loan or SME Term Loan
    expr: LOAN_PRODUCT
    data_type: VARCHAR(13)
    access_modifier: public_access
  - name: MATURITY_DATE
    synonyms:
    - maturity
    - end date
    - final repayment date
    description: Date the loan is due to be fully repaid
    expr: MATURITY_DATE
    data_type: DATE
    access_modifier: public_access
  - name: MATURITY_YEAR
    description: Calendar year in which the loan matures
    expr: YEAR(MATURITY_DATE)
    data_type: NUMBER(4,0)
    access_modifier: public_access
  - name: ORIGINATION_DATE
    expr: ORIGINATION_DATE
    data_type: DATE
    access_modifier: public_access
  - name: TERM_MONTHS
    synonyms:
    - loan term
    - tenor
    description: Contractual term in months
    expr: TERM_MONTHS
    data_type: NUMBER(4,0)
    access_modifier: public_access
- name: LOAN_POSITION
  description: Month-end outstanding principal and days past due per loan, with the borrower and the maturity date
  base_table:
    database: BANK_DEMO
    schema: SEMANTIC
    table: LOAN_POSITION_INPUT
  primary_key:
    columns:
    - LOAN_ID
    - SNAPSHOT_DATE
  dimensions:
  - name: ARREARS_BUCKET
    synonyms:
    - delinquency bucket
    - arrears status
    expr: "CASE WHEN DAYS_PAST_DUE = 0 THEN '0 Current'\n                                         WHEN DAYS_PAST_DUE < 30 THEN '1-29 DPD'\n                                         WHEN DAYS_PAST_DUE < 90 THEN '30-89 DPD'\n                                         ELSE '90+ DPD' END"
    data_type: VARCHAR(9)
    access_modifier: public_access
  - name: DAYS_PAST_DUE
    synonyms:
    - DPD
    - arrears days
    expr: DAYS_PAST_DUE
    data_type: NUMBER(12,0)
    access_modifier: public_access
  - name: MATURITY_BUCKET
    synonyms:
    - maturity profile
    - maturity band
    - time to maturity
    - residual maturity
    description: 'Residual maturity: time from the month end of the position to the loan''s maturity date'
    expr: CASE WHEN MATURITY_DATE <= SNAPSHOT_DATE THEN '0. Matured' WHEN MATURITY_DATE <= DATEADD(year, 1, SNAPSHOT_DATE) THEN '1. Under 1 year' WHEN MATURITY_DATE <= DATEADD(year, 2, SNAPSHOT_DATE) THEN '2. 1-2 years' WHEN MATURITY_DATE <= DATEADD(year, 3, SNAPSHOT_DATE) THEN '3. 2-3 years' WHEN MATURITY_DATE <= DATEADD(year, 5, SNAPSHOT_DATE) THEN '4. 3-5 years' ELSE '5. Over 5 years' END
    data_type: VARCHAR(15)
    access_modifier: public_access
  facts:
  - name: LOAN_PARTY_ID
    description: Borrower of the loan
    expr: BORROWER_PARTY_ID
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: NON_PERFORMING_PRINCIPAL_GBP
    description: Outstanding principal on loans 90 or more days past due
    expr: IFF(DAYS_PAST_DUE >= 90, OUTSTANDING_PRINCIPAL_GBP, 0)
    data_type: NUMBER(29,2)
    access_modifier: public_access
  metrics:
  - name: BORROWERS
    synonyms:
    - borrowing customers
    - customers with loans
    description: Customers with at least one loan with a balance at month end
    expr: COUNT(DISTINCT IFF(OUTSTANDING_PRINCIPAL_GBP > 0, loan_position.loan_party_id, NULL))
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
  - name: LOANS_OUTSTANDING
    synonyms:
    - number of loans
    - loan count
    description: Loans with a balance at month end
    expr: COUNT(DISTINCT IFF(OUTSTANDING_PRINCIPAL_GBP > 0, LOAN_ID, NULL))
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
  - name: NON_PERFORMING_PRINCIPAL
    synonyms:
    - NPL balance
    - non-performing loans
    description: Month-end outstanding principal on loans 90+ days past due, GBP
    expr: SUM(loan_position.non_performing_principal_gbp)
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
  - name: OUTSTANDING_PRINCIPAL
    synonyms:
    - gross loans
    - loan book
    - loans outstanding
    - loan portfolio
    - total loans
    - lending book
    - outstanding balance
    description: Sum of month-end outstanding loan principal, GBP. Semi-additive over time
    expr: SUM(OUTSTANDING_PRINCIPAL_GBP)
    access_modifier: public_access
    non_additive_dimensions:
    - table: CALENDAR
      dimension: MONTH_END_DATE
      sort_direction: ascending
      null_order: last
- name: PARTY
  synonyms:
  - customer
  - client
  - counterparty
  - customers
  description: 'Party: person or organisation the bank has a relationship with, with segment, KYC status and relationship manager (CRM)'
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: PARTY
  primary_key:
    columns:
    - PARTY_ID
  dimensions:
  - name: CUSTOMER_SEGMENT
    synonyms:
    - segment
    - customer tier
    description: RETAIL, PREMIER or SME
    expr: CUSTOMER_SEGMENT
    data_type: VARCHAR(7)
    access_modifier: public_access
  - name: KYC_STATUS
    synonyms:
    - KYC
    - know your customer status
    description: VERIFIED, PENDING or EXPIRED
    expr: KYC_STATUS
    data_type: VARCHAR(8)
    access_modifier: public_access
  - name: ONBOARDED_DATE
    expr: ONBOARDED_DATE
    data_type: DATE
    access_modifier: public_access
  - name: PARTY_ID
    expr: PARTY_ID
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: PARTY_NAME
    synonyms:
    - customer name
    - client name
    - business name
    description: Customer or business name. Masked to initials for some roles
    expr: PARTY_NAME
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: PARTY_SOURCE_SYSTEM
    description: System of record for the Party
    expr: SOURCE_SYSTEM
    data_type: VARCHAR(3)
    access_modifier: public_access
  - name: PARTY_TYPE
    description: INDIVIDUAL or ORGANISATION
    expr: PARTY_TYPE
    data_type: VARCHAR(12)
    access_modifier: public_access
  - name: RM_ID
    description: Relationship manager who owns the customer
    expr: RM_ID
    data_type: VARCHAR(4)
    access_modifier: public_access
  metrics:
  - name: CUSTOMER_COUNT
    synonyms:
    - number of customers
    - customers on record
    description: Number of Parties on record
    expr: COUNT(PARTY_ID)
    access_modifier: public_access
- name: RELATIONSHIP_MANAGER
  synonyms:
  - RM
  - banker
  - account manager
  description: Relationship managers who own each customer book
  base_table:
    database: BANK_DEMO
    schema: SILVER
    table: RELATIONSHIP_MANAGER
  primary_key:
    columns:
    - RM_ID
  dimensions:
  - name: RM_NAME
    synonyms:
    - relationship manager
    - RM
    - banker
    description: Relationship manager who owns the customer
    expr: RM_NAME
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: RM_REGION
    synonyms:
    - region
    - area
    expr: REGION
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: RM_TEAM
    description: Personal & Premier or Business Banking
    expr: TEAM
    data_type: VARCHAR(16777216)
    access_modifier: public_access
metrics:
- name: COMPLAINT_RATE
  synonyms:
  - complaint rate
  - complaints per interaction
  description: Complaints as a share of interactions
  expr: DIV0(interaction.complaints, interaction.interactions)
  access_modifier: public_access
- name: LOAN_TO_DEPOSIT_RATIO
  synonyms:
  - LDR
  - loan to deposit ratio
  description: Outstanding loan principal divided by customer deposits at the same month end
  expr: DIV0(loan_position.outstanding_principal, account_balance.total_deposits)
  access_modifier: public_access
- name: NPL_RATIO
  synonyms:
  - NPL ratio
  - non-performing loan ratio
  description: Non-performing principal (90+ DPD) divided by outstanding principal
  expr: DIV0(loan_position.non_performing_principal, loan_position.outstanding_principal)
  access_modifier: public_access
relationships:
